import React from "react";

function Home() {
  return (
    <div style={styles.wrapper}>
      {/* Üst Çizgiler ve Noktalar */}
      <div style={styles.topBar}>
        <div style={styles.dots}></div>
        <div style={styles.line}></div>
      </div>

      {/* Ana İçerik */}
      <div style={styles.content}>
        {/* Sol Kesik Çizgi */}
        <div style={styles.sideLineLeft}></div>

        {/* İçerik Kutusu (Görseller Burada) */}
        <div style={styles.contentBox}>
          {/* Görseller */}
          <img
            src="https://www.techcareer.net/_next/image?url=https%3A%2F%2Fcdn.gcp.techcareer.net%2F1112_412_2_cd52574011%2F1112_412_2_cd52574011.png&w=1200&q=100"
            alt="Slide 1"
            style={styles.image}
          />
          <img
            src="https://www.techcareer.net/_next/image?url=https%3A%2F%2Fcdn.gcp.techcareer.net%2FTR_1112_412_de17b90249%2FTR_1112_412_de17b90249.png&w=1200&q=100"
            alt="Slide 2"
            style={styles.image}
          />
          <img
            src="https://www.techcareer.net/_next/image?url=https%3A%2F%2Fcdn.gcp.techcareer.net%2FBanner_TR_1112_412_6c2ce3564b%2FBanner_TR_1112_412_6c2ce3564b.png&w=1200&q=100"
            alt="Slide 3"
            style={styles.image}
          />
          <img
            src="https://www.techcareer.net/_next/image?url=https%3A%2F%2Fcdn.gcp.techcareer.net%2F1112_412_47abc9d7c5%2F1112_412_47abc9d7c5.png&w=1200&q=100"
            alt="Slide 4"
            style={styles.image}
          />
        </div>

        {/* Sağ Kesik Çizgi */}
        <div style={styles.sideLineRight}></div>
      </div>

      {/* Alt Mavi Bar */}
      <div style={styles.bottomBar}></div>
    </div>
  );
}

const styles = {
  wrapper: {
    position: "relative",
    width: "1024px", // Tasarıma uygun genişlik
    margin: "0 auto",
    marginTop: "50px",
    backgroundColor: "#FFFFFF",
  },
  topBar: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    width: "1024px",
    margin: "0 auto",
    padding: "10px 0",
  },
  dots: {
    width: "30px",
    height: "11px",
    backgroundColor: "#293349",
    borderRadius: "3px",
  },
  line: {
    width: "143px",
    height: "17px",
    backgroundColor: "#293349",
  },
  content: {
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    marginTop: "20px",
    height: "400px",
  },
  sideLineLeft: {
    width: "17px",
    height: "140px",
    backgroundColor: "#293349",
  },
  contentBox: {
    width: "987px", // İçerik genişliği
    height: "400px",
    backgroundColor: "#293349",
    borderRight: "15px solid #00C26D",
    borderBottom: "15px solid #00C26D",
    display: "flex", // Görseller için düzen
    justifyContent: "space-around",
    alignItems: "center",
    padding: "10px",
    overflow: "hidden",
  },
  image: {
    width: "200px",
    height: "auto",
    borderRadius: "5px",
  },
  sideLineRight: {
    width: "17px",
    height: "140px",
    backgroundColor: "#293349",
  },
  bottomBar: {
    width: "100%",
    height: "178px",
    backgroundColor: "#293349",
    marginTop: "20px",
  },
};

export default EventsSlider;
